970  /* Given the current location in buf, _libssh2_check_length ensures
   971     callers can read the next len number of bytes out of the buffer
   972     before reading the buffer content */
   973
   974  int _libssh2_check_length(struct string_buf *buf, size_t len)
   975  {
   976      unsigned char *endp = &buf->data[buf->len];
   977      size_t left = endp - buf->dataptr;
   978      return (len <= left) && (left <= buf->len);
   979  }
   980
   981  int _libssh2_eob(struct string_buf *buf)
   982  {
   983      unsigned char *endp = &buf->data[buf->len];
   984      return buf->dataptr >= endp;
   985  }
